#include "OriginalGameCar.h"
#include "OriginalLogic.h"
#include "physics/OriginalVehiclePhysics.h"
#include <iostream>
#include <fstream>
#include <stdexcept>
namespace source=r3d::game::originalrace::source;
namespace phys=r3d::physics;
source::GameCar::FixedStepInput input(int move){source::GameCar::FixedStepInput in;in.manualSteering=true;if(move==1)in.brake=1;if(move==2)in.reverse=1;if(move==3)in.throttle=1;return in;}
void zeroMotor(source::GameCar& car){source::GameCar::MotorDescription motor;motor.maximumTorque=0;motor.brakeTorque=0;motor.restBrakeTorque=0;car.ConfigureMotor(motor);}
int main(int argc,char**argv){try{if(argc!=2)return 2;std::ofstream out(argv[1]);
for(int attached=0;attached<2;++attached)for(int previous=0;previous<4;++previous)for(int next=0;next<4;++next){source::GameCar car;zeroMotor(car);car.SetMoveCar(static_cast<source::GameCar::MoveCarState>(previous));car.SetPhysicsActorAvailable(attached!=0);car.SetMoveCar(static_cast<source::GameCar::MoveCarState>(next));const auto cmd=car.OnFixedStepDrive(1.0F/60,input(next),{});out<<"{\"event\":\"wake.sample\",\"attached\":"<<(attached?"true":"false")<<",\"previous\":"<<previous<<",\"next\":"<<next<<",\"requested\":"<<(cmd.wakeBody?"true":"false")<<"}\n";if(car.ConsumeWakeBodyRequest())throw std::runtime_error("wake event consumed twice");}
{source::GameCar car;zeroMotor(car);const int attached[]={0,1,1,1,1,0,1,1};const int move[]={3,3,0,1,1,2,2,3};for(unsigned i=0;i<8;++i){car.SetPhysicsActorAvailable(attached[i]!=0);car.SetMoveCar(static_cast<source::GameCar::MoveCarState>(move[i]));auto cmd=car.OnFixedStepDrive(1.0F/60,input(move[i]),{});out<<"{\"event\":\"wake.sequence\",\"tick\":"<<i<<",\"attached\":"<<(attached[i]?"true":"false")<<",\"next\":"<<move[i]<<",\"requested\":"<<(cmd.wakeBody?"true":"false")<<"}\n";}}
phys::WorldDescription desc;desc.gravity=0;desc.includeDeathPlane=false;desc.vehicle.mass=1000;desc.vehicle.halfExtents={1,1,1};desc.vehicle.centerOfMass={0,0,0};desc.vehicle.shapePosition={0,0,0};desc.vehicle.bodyLinearDamping=0;desc.vehicle.bodyAngularDamping=0;desc.vehicle.bodySleepEnergyThreshold=.005F;desc.vehicle.wheelContactsEnabled=false;desc.vehicle.maximumTorque=0;desc.vehicle.differentialRatio=3.42F;desc.vehicle.maximumRpm=7000;desc.vehicle.idlingRpm=1000;desc.vehicle.restBrakeTorque=0;desc.vehicle.brakeTorque=0;for(int i=0;i<4;++i){phys::WheelDescription w;w.position={i<2?1.0F:-1.0F,i%2?1.0F:-1.0F,-.5F};w.radius=.5F;w.width=.2F;w.suspensionTravel=.4F;w.inverseMass=1;w.flags=64;w.driven=i<2;desc.vehicle.wheels.push_back(w);}
phys::TriangleMesh floor;floor.vertices={{-500,-500,-1000},{500,-500,-1000},{500,500,-1000},{-500,500,-1000}};floor.indices={0,1,2,0,2,3};desc.collisionMeshes.push_back(floor);std::string error;auto world=phys::createOriginalVehicleWorld(desc,error);if(!world)throw std::runtime_error(error);source::GameCar car;zeroMotor(car);car.SetPhysicsActorAvailable(true);int move=0;world->setVehicleFixedStepController([&](std::size_t,float dt,const phys::VehicleInput&,const phys::VehicleFixedStepState&){auto cmd=car.OnFixedStepDrive(dt,input(move),{});phys::VehicleDriveCommand result;result.engineRpm=cmd.rpm;result.gear=cmd.gear;result.motorTorque=cmd.motorTorque;result.brakeTorque=cmd.brakeTorque;result.wakeBody=cmd.wakeBody;result.applyAngularStabilization=false;result.applyExtraGravity=false;return result;});for(unsigned tick=0;tick<360;++tick){move=tick<30?0:tick<90?3:tick<150?1:tick<210?2:tick<270?3:0;phys::VehicleInput in;in.throttle=move==3?1:0;in.brake=move==1?1:0;in.reverse=move==2?1:0;world->step(1.0F/60,in);out<<"{\"event\":\"wake.schedule\",\"tick\":"<<tick<<",\"next\":"<<move<<",\"awake\":"<<(world->vehicle().bodyAwake?"true":"false")<<"}\n";}
return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 3;}}
